#define MAX_PATH_LEN 4096

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[MAX_PATH_LEN];
    int fd;
    ssize_t bytes_written;
    struct stat sb;

    // Format the path using the provided format string
    if (snprintf(path, sizeof(path), var, iface) < 0) {
        return -1;
    }

    // Check for path traversal vulnerabilities
    if (strstr(path, "../") != NULL) {
        return -1;
    }

    // Check if file exists and is a regular file
    if (stat(path, &sb) != 0) {
        return -1;
    }

    if (!S_ISREG(sb.st_mode)) {
        return -1;
    }

    // Open the file for writing
    fd = open(path, O_WRONLY | O_TRUNC);
    if (fd == -1) {
        return -1;
    }

    // Write the value as a string
    char value_str[12]; // Enough to hold uint32_t as a string
    snprintf(value_str, sizeof(value_str), "%u", val);

    bytes_written = write(fd, value_str, strlen(value_str));
    if (bytes_written < 0 || (size_t)bytes_written != strlen(value_str)) {
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int set_iface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
