int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[256];
    FILE *fp;

    // Construct the file path using the interface name and variable format
    snprintf(path, sizeof(path), var, iface);

    // Check for path traversal vulnerabilities
    if (strchr(path, '/') != NULL) {
        fprintf(stderr, "Error: Path traversal attempt in variable '%s' for interface '%s'\n", name, iface);
        return -1;
    }

    // Open the file for writing
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Write the value to the file
    if (fprintf(fp, "%u", val) < 0) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    // Close the file
    fclose(fp);
    return 0;
}

#include <stdint.h>
