int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[256];
    FILE *fp;
    int ret = -1;

    if (!iface || !var || !name) {
        return -1;
    }

    if (snprintf(path, sizeof(path), var, iface) >= sizeof(path)) {
        return -1;
    }

    if (access(path, F_OK) != 0) {
        return -1;
    }

    if ((fp = fopen(path, "w")) == NULL) {
        return -1;
    }

    if (fprintf(fp, "%u\n", val) < 0) {
